long long maxComfortSum(vector<long long>& coins, vector<pair<long long, long long>>& houses) {
    // 将朋友按金币数从小到大排序
    sort(coins.begin(), coins.end());

    // 将房子按价格从小到大排序，pair = {价格, 舒适度}
    sort(houses.begin(), houses.end());

    // 最大堆，存储当前可以买的房子的舒适度
